async function seedPolicy_Org_createTask(h: AverriTestHarness, env: Env, mode: SeedMode, fixture: string): Promise<void> {
  if (mode === "falsify") {
    await seed_Org_createTask_policy_0(h, env, "falsify");
    await seed_Org_createTask_policy_1(h, env, "falsify");
    return;
  }
  if (env.actor?.["type"] === "user") {
    await seed_Org_createTask_policy_0(h, env, "satisfy");
    if (["allow", "public", "opaque"].includes(await h.policyDecision("Action:Org.createTask", fixture, env.input))) return;
  }
  if (env.actor?.["type"] === "apiKey") {
    await seed_Org_createTask_policy_1(h, env, "satisfy");
  }
  void fixture;
}

