async function allowedFixture_Org_createTask(h: AverriTestHarness, input: Record<string, unknown>): Promise<string> {
  for (const fixture of FIXTURES) {
    if (fixture === "anonymous") continue;
    const env: Env = { input, actor: h.actor(fixture) };
    await seedPolicy_Org_createTask(h, env, "satisfy", fixture);
    const decision = await h.policyDecision("Action:Org.createTask", fixture, input);
    if (decision === "allow" || decision === "public" || decision === "opaque") return fixture;
  }
  throw new Error("no actor fixture in FIXTURES is allowed by Policy:Org.Member for this input; add a fixture to config.actors or seed the rows the policy needs");
}

async function invokeAllowed_Org_createTask(h: AverriTestHarness, input: Record<string, unknown>, options?: { headers?: Record<string, string> }): Promise<{ res: Invoked; fixture: string; env: Env }> {
  const fixture = await allowedFixture_Org_createTask(h, input);
  const env: Env = { input, actor: h.actor(fixture) };
  await seedRequires_Org_createTask(h, env);
  await seedSubject_Org_createTask(h, env);
  const res = await h.invoke("Action:Org.createTask", fixture, input, options);
  return { res, fixture, env };
}

