describe("[Test:gen/Project.invariant]", () => {
  // Every invariant is evaluated over findMany() of the model (observe-mode diff; declared mode also reports it as 500 PostconditionFailed).
  const INVARIANTS = ["Contract:Project.invariant.archivedHasTimestamp", "Contract:Project.invariant.activeHasNoArchivedAt", "Contract:Project.invariant.taskCounterNonNegative", "Contract:Project.invariant.statusIsKnown"];
  it("[Test:gen/Project.invariant] invariants hold on the current rows", async () => {
    expect(await h.invariantViolations("Entity:Project")).toEqual([]);
  });
  const WRITERS = ["Action:Org.archiveProject", "Action:Org.createProject", "Action:Org.createTask"] as const;
  async function runWriter(writer: (typeof WRITERS)[number]): Promise<Invoked> {
    switch (writer) {
      case "Action:Org.archiveProject": {
        const input = drawInput(h, "Action:Org.archiveProject", input_valid_Org_archiveProject);
        return (await invokeAllowed_Org_archiveProject(h, input)).res;
      }
      case "Action:Org.createProject": {
        const input = drawInput(h, "Action:Org.createProject", input_valid_Org_createProject);
        return (await invokeAllowed_Org_createProject(h, input)).res;
      }
      case "Action:Org.createTask": {
        const input = drawInput(h, "Action:Org.createTask", input_valid_Org_createTask);
        return (await invokeAllowed_Org_createTask(h, input)).res;
      }
    }
  }
  it("[Test:gen/Project.invariant] 1-5 generated writes preserve the invariants", async () => {
    await fc.assert(fc.asyncProperty(fc.array(fc.constantFrom(...WRITERS), { minLength: 1, maxLength: 5 }), async (sequence) => {
      for (const writer of sequence) {
        const res = await runWriter(writer);
        if (res.status === 500) expect(INVARIANTS, `${writer} reported an invariant failure`).not.toContain(errorBody(res).contract);
        expect(await h.invariantViolations("Entity:Project"), `after ${writer}`).toEqual([]);
      }
    }), { numRuns: NUM_RUNS });
  }, PROPERTY_TIMEOUT_MS);
});
